    async function openAuthenticatedApp(showWelcome=false){
      try{
        const cloudState=await window.llanqueCloud.load(),cloudKeys=new Set(cloudState.stateKeys);
        const remote=key=>{try{return JSON.parse(localStorage.getItem(`llanque-demo-${key}`)||'null')}catch{return null}};
        const replace=(target,value)=>{target.splice(0,target.length,...(Array.isArray(value)?value:[]))};
        for(const key of ['inventory','clients','history','movements','attendance','personnel'])replace(
          ({inventory:catalog,clients,history:histories,movements,attendance,personnel})[key],
          cloudKeys.has(`llanque-demo-${key}`)?remote(key):[]
        );
        deviceCode=localStorage.getItem('llanque-demo-device-code')||deviceCode;
        if(!cloudKeys.has('llanque-demo-inventory'))localStorage.setItem('llanque-demo-inventory',JSON.stringify(catalog));
        if(!cloudKeys.has('llanque-demo-clients'))localStorage.setItem('llanque-demo-clients',JSON.stringify(clients));
        if(!cloudKeys.has('llanque-demo-history'))localStorage.setItem('llanque-demo-history',JSON.stringify(histories));
        if(!cloudKeys.has('llanque-demo-movements'))localStorage.setItem('llanque-demo-movements',JSON.stringify(movements));
        if(!cloudKeys.has('llanque-demo-attendance'))localStorage.setItem('llanque-demo-attendance',JSON.stringify(attendance));
        if(!cloudKeys.has('llanque-demo-personnel'))localStorage.setItem('llanque-demo-personnel',JSON.stringify(personnel));
        renderClients(clients[0]?.name||'');renderPeople();renderInventory();renderMovements();renderKardex();renderAttendance();
        setLoggedIn(true);switchView('home');
        if(showWelcome)showLoginWelcome();
      }catch(error){
        window.llanqueCloud?.setStatus('Sin conexión',true);
        const message=error?.message||window.llanqueCloudError||'No se pudo conectar con Supabase.';
        const loginError=document.querySelector('#loginError');
        loginError.textContent=`No se pudo cargar la base de datos: ${message}`;
        loginError.classList.add('show');
      }
    }
    document.querySelector('#loginForm').addEventListener('submit',async e=>{
      e.preventDefault();const loginError=document.querySelector('#loginError');
      if(!window.llanqueCloud){loginError.textContent=window.llanqueCloudError||'No se pudo cargar Supabase. Revisa tu conexión a internet.';loginError.classList.add('show');return}
      const email=document.querySelector('#loginUser').value.trim(),password=document.querySelector('#loginPassword').value;
      const {error}=await window.llanqueCloud.client.auth.signInWithPassword({email,password});
      if(error){loginError.textContent='Correo o contraseña incorrectos. Verifica que el usuario exista en Supabase > Authentication > Users.';loginError.classList.add('show');document.querySelector('#loginPassword').value='';return}
      loginError.classList.remove('show');await openAuthenticatedApp(true);
    });
