    function drawClientPickerOptions(query=''){const box=document.querySelector('#clientPickerOptions'),q=query.trim().toLocaleLowerCase('es'),filtered=clients.map((c,index)=>({c,index})).filter(({c})=>`${c.name} ${c.document||c.ci||''}`.toLocaleLowerCase('es').includes(q));box.innerHTML=filtered.length?filtered.map(({c,index})=>`<button type="button" class="client-picker-option${document.querySelector('#client').value===c.name?' selected':''}" role="option" aria-selected="${document.querySelector('#client').value===c.name}" data-client-index="${index}"><span>${escapeHtml(c.name)}</span><small>${escapeHtml(c.document||c.ci||'Sin documento')}</small></button>`).join(''):'<div class="client-picker-empty">No se encontraron clientes.</div>';box.scrollTop=0;box.querySelectorAll('[data-client-index]').forEach(option=>option.onclick=()=>{const client=clients[Number(option.dataset.clientIndex)],select=document.querySelector('#client');select.value=client.name;document.querySelector('#clientPickerButton span').textContent=`${client.name}${client.document?' · '+client.document:''}`;document.querySelector('#clientPickerMenu').hidden=true;document.querySelector('#clientPickerButton').setAttribute('aria-expanded','false');document.querySelector('#editClientBtn').disabled=!select.value;select.dispatchEvent(new Event('change',{bubbles:true}))})}
