    function collectSale(){const items=[...tbody.querySelectorAll('tr')].map(tr=>{const product=catalog.find(item=>item[0]===tr.dataset.code);if(!product)return null;const price=Number(tr.querySelector('.unit-price').value)||0,qty=Number(tr.querySelector('.qty').value)||0,discount=Math.min(price*qty,Math.max(0,Number(tr.querySelector('.line-discount').value)||0));return {code:product[0],name:product[1],unit:tr.querySelector('.unit').value,price,qty,discount,total:Math.max(0,price*qty-discount)}}).filter(Boolean),subtotalValue=items.reduce((sum,item)=>sum+item.price*item.qty,0),discountsValue=items.reduce((sum,item)=>sum+item.discount,0),extraDiscountValue=Math.min(Math.max(0,subtotalValue-discountsValue),Math.max(0,Number(document.querySelector('#discount').value)||0)),totalValue=Math.max(0,subtotalValue-discountsValue-extraDiscountValue),clientName=document.querySelector('#client').value,buyer=clients.find(client=>client.name===clientName);return {id:'D-'+Date.now().toString().slice(-7),date:document.querySelector('#date').value,warehouse:document.querySelector('#warehouse').value,client:clientName,clientDocument:buyer?.document||buyer?.ci||'',payment:document.querySelector('#payment').value,paymentForm:document.querySelector('#paymentForm').value,notes:document.querySelector('#notes').value,items,subtotal:fmt(subtotalValue),discounts:fmt(discountsValue),extraDiscount:fmt(extraDiscountValue),total:fmt(totalValue),subtotalValue,discountsValue,extraDiscountValue,totalValue,created:new Date().toLocaleString('es-BO')}}
    function exportSalesExcel(){if(!histories.length){showToast('Todavía no hay ventas demo para descargar.');return}const rows=histories.flatMap(sale=>sale.items.map(item=>[sale.id,sale.date||'',sale.created||'',sale.warehouse||'',sale.client||'',sale.payment||'',sale.paymentForm||'',item.code,item.name,item.qty,Number(item.price)||0,Number(item.discount)||0,Number(item.total)||0,sale.total||'']));downloadCsv('LLANQUE_ventas_demo.csv',['Documento','Fecha','Fecha de registro','Almacén','Cliente','Método de pago','Forma de pago','Código','Producto','Cantidad','Precio unitario (Bs.)','Descuento (Bs.)','Total producto (Bs.)','Total venta (Bs.)'],rows);showToast('Ventas demo descargadas; abre el archivo CSV con Excel.')}
    function renderHistory(){openModal('Historial de ventas demo',`<div class="tabs"><button class="tab active" type="button">En este navegador</button><button class="tab" type="button" id="clearHistory">Borrar historial demo</button></div><div class="toolbar"><button class="btn btn-light" type="button" id="historyDownloadSales" ${histories.length?'':'disabled'}>Descargar ventas Excel</button></div><div class="history-list">${histories.length?histories.slice().reverse().map(h=>`<div class="history-item"><div><strong>${escapeHtml(h.id)}</strong><br><small>${escapeHtml(h.created)} · ${escapeHtml(h.client||'Sin cliente')}</small></div><strong>${escapeHtml(h.total)}</strong></div>`).join(''):'<div class="empty">Todavía no hay registros de demostración.</div>'}</div>`);document.querySelector('#historyDownloadSales').onclick=exportSalesExcel;const clear=document.querySelector('#clearHistory');clear.onclick=()=>{histories.splice(0);localStorage.setItem('llanque-demo-history','[]');persistDemo();renderHistory();showToast('Historial demo borrado de este navegador.')}}
    document.querySelector('#historyBtn').addEventListener('click',renderHistory);document.querySelector('#downloadSales').addEventListener('click',exportSalesExcel);
    function showReceipt(sale){const buyer=clients.find(client=>client.name===sale.client),doc=buyer?.document||buyer?.ci||'0',dateValue=sale.date?new Date(sale.date):new Date(sale.created),dateText=Number.isNaN(dateValue.getTime())?sale.created:dateValue.toLocaleString('es-BO');openModal('Recibo de LLANQUE',`<article id="receipt" class="receipt-sheet"><header class="receipt-brand"><img class="receipt-logo" src="logo-rodaracing.png" alt="Rodaracing · Potencia, movimiento, confianza" style="width:58%;height:80px;object-fit:contain;background:transparent!important;padding:0;border:0;border-radius:0;filter:drop-shadow(0 2px 6px #00122a80)"><div class="receipt-number"><strong>Recibo N° ${escapeHtml(sale.id)}</strong><br><span>NIT/CI/EX: ${escapeHtml(doc)}</span></div></header><h3 class="receipt-title">RECIBO</h3><div class="receipt-meta"><p><b>Fecha:</b> ${escapeHtml(dateText)}</p><p><b>Nombre/Razón Social:</b> ${escapeHtml(sale.client||'Consumidor final')}</p></div><table class="receipt-items"><thead><tr><th>CÓDIGO PRODUCTO</th><th>CANTIDAD</th><th>UNIDAD MEDIDA</th><th>DESCRIPCIÓN</th><th>PRECIO UNITARIO</th><th>DESCUENTO</th><th>SUBTOTAL</th></tr></thead><tbody>${sale.items.map(item=>`<tr><td>${escapeHtml(item.code)}</td><td class="num">${item.qty}</td><td>${escapeHtml(item.unit||'Unidad')}</td><td>${escapeHtml(item.name)}</td><td class="num">${fmt(item.price)}</td><td class="num">${fmt(item.discount)}</td><td class="num">${fmt(item.total)}</td></tr>`).join('')}</tbody></table><div class="receipt-summary"><div><span>SUBTOTAL</span><strong>${escapeHtml(sale.subtotal)}</strong></div><div><span>DESCUENTO</span><strong>${fmt((Number(sale.discountsValue)||0)+(Number(sale.extraDiscountValue)||0))}</strong></div><div class="receipt-grand-total"><span>TOTAL</span><strong>${escapeHtml(sale.total)}</strong></div></div><div class="receipt-operator"><b>Operador:</b><span>LLANQUE</span></div><footer>GRACIAS POR SU COMPRA</footer></article><div class="dialog-actions no-print"><button class="btn btn-light" id="receiptClose">Cerrar</button><button class="btn btn-blue" id="receiptPrint">Imprimir recibo</button></div>`);document.querySelector('#receiptClose').onclick=closeModal;document.querySelector('#receiptPrint').onclick=()=>window.print()}
    document.querySelector('#printBtn').addEventListener('click',()=>showReceipt(collectSale()));
    function currentSaleDateTime(){const now=new Date();return new Date(now.getTime()-now.getTimezoneOffset()*60000).toISOString().slice(0,16)}
    function showSaleFeedback(message,isError=true){const notice=document.querySelector('#notice');notice.textContent=message;notice.classList.toggle('error',isError);notice.classList.add('show')}
    function resetDemo(){document.querySelector('#saleForm').reset();renderClients(clients.some(client=>client.name==='Consumidor final')?'Consumidor final':(clients[0]?.name||''));document.querySelector('#date').value=currentSaleDateTime();tbody.innerHTML='';addRow();document.querySelector('#creditFields').classList.remove('on');document.querySelector('#mixedPayment').hidden=true;document.querySelector('#payLines').innerHTML='';document.querySelector('#notice').classList.remove('show','error');calculate()}
    document.querySelector('#newBtn').addEventListener('click',resetDemo);document.querySelector('#clearBtn').addEventListener('click',resetDemo);document.querySelector('#cancel').addEventListener('click',()=>{resetDemo();showToast('Formulario de demostración reiniciado.')});
    async function saveSale(e){
      e?.preventDefault();
      document.querySelector('#notice').classList.remove('show','error');
      const sale=collectSale();
      if(!sale.items.length){showSaleFeedback('No se guardó: agrega un producto desde Buscar Productos.');return}
      if(sale.items.some(item=>!Number.isFinite(item.qty)||item.qty<1)){showSaleFeedback('No se guardó: la cantidad de cada producto debe ser al menos 1.');return}
      if(!sale.client){showSaleFeedback('No se guardó: selecciona un cliente.');return}
      if(document.querySelector('#payment').value==='Mixto'){
        const amount=[...document.querySelectorAll('#payLines input')].reduce((a,x)=>a+(Number(x.value)||0),0),total=readTotal();
        if(Math.abs(amount-total)>.009){showSaleFeedback('No se guardó: completa la distribución del pago mixto.');return}
      }
      if(sale.paymentForm==='Crédito'&&Number(document.querySelector('#downPayment').value)>readTotal()){showSaleFeedback('No se guardó: el anticipo no puede superar el total.');return}
      for(const item of sale.items){const product=catalog.find(x=>x[0]===item.code);if(!product||item.qty>Number(product[3])){showSaleFeedback(`No se guardó: stock insuficiente para ${item.name}. Disponible: ${product?.[3]||0}.`);return}}
      for(const item of sale.items){const product=catalog.find(x=>x[0]===item.code);product[3]-=item.qty}
      histories.push(sale);
      movements.push({id:sale.id,type:'Salida por Venta',date:sale.date,warehouse:sale.warehouse,client:sale.client,items:sale.items.map(i=>({...i,direction:'out'})),total:sale.total,status:'Activo',created:sale.created});
      if(!persistDemo()){for(const item of sale.items){const product=catalog.find(x=>x[0]===item.code);if(product)product[3]+=item.qty}histories.pop();movements.pop();try{localStorage.setItem('llanque-demo-inventory',JSON.stringify(catalog));localStorage.setItem('llanque-demo-movements',JSON.stringify(movements));localStorage.setItem('llanque-demo-history',JSON.stringify(histories))}catch(_){}showSaleFeedback('La venta no se completó porque el navegador no pudo guardarla. Descarga un respaldo o libera espacio e inténtalo de nuevo.');return}
      if(!await window.llanqueCloud.flush()){for(const item of sale.items){const product=catalog.find(x=>x[0]===item.code);if(product)product[3]+=item.qty}histories.pop();movements.pop();persistDemo();await window.llanqueCloud.flush();showSaleFeedback('La venta no se guardó en la nube. Revisa tu conexión e inténtalo de nuevo.');return}
      renderInventory();renderMovements();renderKardex();renderPeople();
      resetDemo();
      switchView('movements');
      showReceipt(sale);
      showToast('Venta guardada. El recibo está listo para revisar o imprimir.',5000);
    }
    document.querySelector('#saveSaleButton').addEventListener('click',saveSale);
    document.querySelector('#saleForm').addEventListener('submit',saveSale);
    document.querySelector('#saleForm').addEventListener('reset',()=>setTimeout(()=>{calculate();document.querySelector('#editClientBtn').disabled=!document.querySelector('#client').value},0));document.querySelector('#discount').addEventListener('change',calculate);document.querySelector('#date').value=currentSaleDateTime();addRow();

/* Tesorería local de demostración: estos registros se guardan en este navegador. */
const treasuryAccounts=[
  ['5201001003','SUELDOS Y SALARIOS COCHABAMBA'],['5201012003','PASAJES COCHABAMBA'],['5202001004','LUZ COCHABAMBA'],['5202002003','AGUA COCHABAMBA'],['5202003004','SERVICIOS INTERNET TIGO COCHABAMBA'],['5202005003','MATERIAL DE LIMPIEZA COCHABAMBA'],['5202006003','TRANSPORTE NACIONAL COCHABAMBA'],['5202012003','ALQUILERES COCHABAMBA'],['5202015003','SEGURIDAD, MONITOREO Y VIGILANCIA COCHABAMBA'],['5202018003','MATERIAL DE ESCRITORIO COCHABAMBA'],['5206002003','OTROS GASTOS COCHABAMBA'],['5501009004','GASTOS DN RUBEN COCHABAMBA'],['1101001004','CAJA COCHABAMBA']
];
let treasuryEntries=[];
try{const stored=JSON.parse(localStorage.getItem('llanque-demo-treasury')||'[]');if(Array.isArray(stored))treasuryEntries=stored}catch{}
function treasuryOptions(selected='',includeCash=true){return treasuryAccounts.filter(([code])=>includeCash||code!=='1101001004').map(([code,name])=>`<option value="${code}" ${code===selected?'selected':''}>${code} - ${name} (Presupuesto: Bs. 0.00)</option>`).join('')}
function treasuryMoney(value){return 'Bs. '+(Number(value)||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}
function showTreasuryEntry(){
  const today=localDateValue();
  openModal('Crear Asiento de Tesorería',`<div class="treasury-form"><div class="treasury-entry-top"><div class="field"><label for="treasuryDate">Fecha</label><input id="treasuryDate" type="date" value="${today}"></div><label class="treasury-invoice-check"><input id="treasuryHasInvoice" type="checkbox"> ¿Tiene factura?</label><div class="field treasury-invoice-number" id="treasuryInvoiceWrap" hidden><label for="treasuryInvoice">N° de factura</label><input id="treasuryInvoice" placeholder="Número de factura"></div></div><h3>Cuentas de Tesorería</h3><div class="table-wrap treasury-lines-wrap"><table class="treasury-lines"><thead><tr><th>Cuenta</th><th>Concepto</th><th class="num">Monto</th><th>Acción</th></tr></thead><tbody id="treasuryLines"></tbody><tfoot><tr><th colspan="2" class="num">TOTAL EGRESO:</th><th class="num" id="treasuryTotal">Bs. 0.00</th><th></th></tr></tfoot></table></div><button class="btn btn-light treasury-add-line" type="button" id="treasuryAddLine">⊕ Agregar Fila</button><aside class="transfer-info treasury-note"><b>Nota:</b> El sistema generará un asiento de tipo Egreso con el tipo de cambio actual. Se sincroniza con Supabase en esta instalación; no modifica caja real ni se envía a Xiren.</aside><div class="dialog-actions"><button class="btn btn-light" id="treasuryCancel" type="button">Cancelar</button><button class="btn btn-blue" id="treasurySave" type="button">▣ Guardar Asiento</button></div></div>`);
  modal.classList.add('treasury-entry-open');
  const lines=document.querySelector('#treasuryLines');
  const updateTotal=()=>{const total=[...lines.querySelectorAll('.treasury-amount')].reduce((sum,input)=>sum+(Number(input.value)||0),0);document.querySelector('#treasuryTotal').textContent=treasuryMoney(total)};
  const addLine=()=>{const row=document.createElement('tr');row.innerHTML=`<td><select class="treasury-account"><option value="">-- Seleccionar --</option>${treasuryOptions('',false)}</select></td><td><input class="treasury-concept" placeholder="Concepto" maxlength="120"></td><td><input class="treasury-amount" type="number" min="0.01" step="0.01" placeholder="0.00"></td><td><button class="btn btn-red treasury-remove" type="button" aria-label="Eliminar fila" title="Eliminar fila">▤</button></td>`;lines.append(row);row.querySelector('.treasury-amount').addEventListener('input',updateTotal);row.querySelector('.treasury-remove').onclick=()=>{if(lines.children.length===1){row.querySelectorAll('input').forEach(input=>input.value='');row.querySelector('select').value=''}else row.remove();updateTotal()}};
  document.querySelector('#treasuryHasInvoice').onchange=event=>{document.querySelector('#treasuryInvoiceWrap').hidden=!event.target.checked};
  document.querySelector('#treasuryAddLine').onclick=addLine;
  document.querySelector('#treasuryCancel').onclick=closeModal;
  document.querySelector('#treasurySave').onclick=async()=>{const date=document.querySelector('#treasuryDate').value,hasInvoice=document.querySelector('#treasuryHasInvoice').checked,invoice=document.querySelector('#treasuryInvoice').value.trim(),rows=[...lines.querySelectorAll('tr')].map(row=>({account:row.querySelector('.treasury-account').value,concept:row.querySelector('.treasury-concept').value.trim(),amount:Number(row.querySelector('.treasury-amount').value)}));if(!date){showToast('Selecciona la fecha del asiento.');return}if(hasInvoice&&!invoice){showToast('Escribe el número de factura.');return}if(!rows.length||rows.some(row=>!row.account||!row.concept||!Number.isFinite(row.amount)||row.amount<=0)){showToast('Completa cuenta, concepto y monto válido en cada fila.');return}const now=new Date(),record={id:'AT-'+now.getTime().toString().slice(-8),date,created:now.toISOString(),type:'Egreso',invoice:hasInvoice?invoice:'',cashAccount:'1101001004',user:'LLANQUE (DEMO)',lines:rows,total:rows.reduce((sum,row)=>sum+row.amount,0)};treasuryEntries.push(record);try{localStorage.setItem('llanque-demo-treasury',JSON.stringify(treasuryEntries))}catch(error){treasuryEntries.pop();showToast('No se guardó: el almacenamiento local está lleno.',6000,'warning');return}modal.classList.remove('treasury-entry-open');closeModal();if(!window.llanqueCloud?.flush){showToast(`Asiento ${record.id} quedó en este navegador; no hay conexión activa con Supabase.`,6500,'warning');return}const synced=await window.llanqueCloud.flush();if(synced)showToast(`Asiento ${record.id} guardado y sincronizado con Supabase.`);else showToast(`Asiento ${record.id} se conserva localmente, pero Supabase no confirmó el guardado. Revisa la conexión antes de volver a ingresarlo.`,7500,'warning')};
  addLine();
}
function showTreasuryReport(){
  const today=localDateValue(),defaultAccount='1101001004',recordDates=treasuryEntries.map(entry=>entry.date).filter(Boolean).sort(),reportStart=recordDates.length&&recordDates[0]<today?recordDates[0]:today,reportEnd=recordDates.length&&recordDates.at(-1)>today?recordDates.at(-1):today;
  openModal('Reporte de Tesorería',`<div class="treasury-report"><div class="transfer-info treasury-report-note">ⓘ &nbsp;Los asientos de egreso se reflejan como Debe en su cuenta de gasto y como Haber en Caja.</div><div class="treasury-report-account"><div class="field"><label for="treasuryReportCode">Código de cuenta</label><select id="treasuryReportCode">${treasuryOptions(defaultAccount)}</select></div><div class="field"><label for="treasuryReportName">Cuenta de tesorería</label><input id="treasuryReportName" readonly></div></div><div class="treasury-report-filters"><div class="field"><label for="treasuryFrom">Fecha Desde</label><input type="date" id="treasuryFrom" value="${reportStart}"></div><div class="field"><label for="treasuryTo">Fecha Hasta</label><input type="date" id="treasuryTo" value="${reportEnd}"></div><button class="btn btn-light" id="treasuryRefresh" type="button">⟳ Actualizar</button><button class="btn btn-green" id="treasuryExportTop" type="button">⇩ Excel</button></div><div id="treasuryReportContent"></div><div class="dialog-actions treasury-report-actions"><button class="btn btn-light" id="treasuryReportClose" type="button">⊗ Cerrar</button><button class="btn btn-green" id="treasuryExport" type="button">⇩ Exportar Excel</button></div></div>`);
  modal.classList.add('treasury-report-open');const account=document.querySelector('#treasuryReportCode'),nameInput=document.querySelector('#treasuryReportName'),from=document.querySelector('#treasuryFrom'),to=document.querySelector('#treasuryTo');
  const selectedAccount=()=>treasuryAccounts.find(([code])=>code===account.value)||treasuryAccounts[0];
  const reportRows=()=>{const [code]=selectedAccount();return treasuryEntries.filter(entry=>(!from.value||entry.date>=from.value)&&(!to.value||entry.date<=to.value)).flatMap(entry=>{const lines=Array.isArray(entry.lines)?entry.lines:[];if(code===(entry.cashAccount||defaultAccount)){const amount=Number(entry.total)||lines.reduce((sum,line)=>sum+(Number(line.amount)||0),0);return amount>0?[{entry,concept:lines.map(line=>line.concept).filter(Boolean).join(' · ')||'Egreso de Tesorería',debit:0,credit:amount}]:[]}return lines.filter(line=>line.account===code).map(line=>({entry,concept:line.concept||'—',debit:Number(line.amount)||0,credit:0}))}).sort((a,b)=>a.entry.date.localeCompare(b.entry.date)||String(a.entry.created||'').localeCompare(String(b.entry.created||'')))};
  const render=()=>{const [code,name]=selectedAccount();nameInput.value=name;const rows=reportRows(),debit=rows.reduce((sum,row)=>sum+row.debit,0),credit=rows.reduce((sum,row)=>sum+row.credit,0);document.querySelector('#treasuryReportContent').innerHTML=`<div class="treasury-report-summary"><span>${rows.length} movimiento${rows.length===1?'':'s'} · Debe ${treasuryMoney(debit)} · Haber ${treasuryMoney(credit)}</span><strong>${treasuryMoney(code==='1101001004'?credit:debit)}</strong></div><div class="table-wrap treasury-report-table-wrap"><table class="treasury-report-table"><thead><tr><th>Fecha</th><th>Asiento</th><th>Cheque / Factura</th><th>Concepto</th><th class="num">Debe</th><th class="num">Haber</th></tr></thead><tbody>${rows.length?rows.map(row=>`<tr><td>${escapeHtml(row.entry.date)}</td><td>${escapeHtml(row.entry.id)}</td><td>${escapeHtml(row.entry.invoice||'—')}</td><td>${escapeHtml(row.concept)}</td><td class="num">${row.debit?treasuryMoney(row.debit):'—'}</td><td class="num">${row.credit?treasuryMoney(row.credit):'—'}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">No hay asientos para esta cuenta y período.</td></tr>'}</tbody><tfoot><tr><th colspan="4" class="num">TOTALES</th><th class="num">${debit?treasuryMoney(debit):'—'}</th><th class="num">${credit?treasuryMoney(credit):'—'}</th></tr></tfoot></table></div><p class="hint">El mismo asiento se refleja en ambas cuentas: gasto en Debe y Caja en Haber.</p>`};
  const exportReport=()=>{const [code,name]=selectedAccount(),rows=reportRows().map(row=>[row.entry.date,row.entry.id,row.entry.invoice||'',row.concept,row.debit.toFixed(2),row.credit.toFixed(2),row.entry.user||'LLANQUE (DEMO)']);downloadCsv('LLANQUE_reporte_tesoreria_demo.csv',['Fecha','Asiento','Cheque / Factura','Concepto','Debe (Bs.)','Haber (Bs.)','Usuario'],rows);showToast(`Reporte de ${name} descargado para Excel.`)};
  account.onchange=render;document.querySelector('#treasuryRefresh').onclick=render;from.onchange=render;to.onchange=render;document.querySelector('#treasuryReportClose').onclick=closeModal;document.querySelector('#treasuryExport').onclick=exportReport;document.querySelector('#treasuryExportTop').onclick=exportReport;render();
}
document.querySelector('#openTreasuryEntry').addEventListener('click',()=>{document.querySelectorAll('.nav-dropdown.is-open').forEach(menu=>menu.classList.remove('is-open'));showTreasuryEntry()});
document.querySelector('#openTreasuryReport').addEventListener('click',()=>{document.querySelectorAll('.nav-dropdown.is-open').forEach(menu=>menu.classList.remove('is-open'));showTreasuryReport()});



/* Apertura y cierre de caja local con sincronización por el estado de Supabase. */
const cashDenominations=[200,100,50,20,10,5,2,1,0.5,0.2,0.1];
let cashSessions=[];
try{const stored=JSON.parse(localStorage.getItem('llanque-demo-cash-sessions')||'[]');if(Array.isArray(stored))cashSessions=stored}catch{}
function cashMoney(value){return 'Bs. '+(Number(value)||0).toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2})}
function cashCountsMarkup(values={}){const left=[200,50,10,2,0.5,0.1],right=[100,20,5,1,0.2];const column=items=>`<table class="cash-denom-table"><thead><tr><th>Denominación (Bs.)</th><th>Denom.</th><th>Cantidad</th><th>Subtotal</th></tr></thead><tbody>${items.map(value=>`<tr><td><strong>Bs. ${value.toFixed(value%1?1:0)}</strong></td><td>Denom.</td><td><input class="cash-count" type="number" min="0" step="1" value="${Number(values[String(value)])||0}" data-denomination="${value}" aria-label="Cantidad de billetes o monedas de ${value} bolivianos"></td><td class="cash-subtotal">Bs. 0.00</td></tr>`).join('')}</tbody></table>`;return `<div class="cash-denom-grid">${column(left)}${column(right)}</div>`}
async function syncCashSessions(recordId,action){try{localStorage.setItem('llanque-demo-cash-sessions',JSON.stringify(cashSessions))}catch(error){showToast('No se guardó la caja: almacenamiento local lleno.',6500,'warning');return false}if(!window.llanqueCloud?.flush){showToast(`Caja ${recordId} guardada localmente, sin conexión con Supabase.`,6500,'warning');return false}const synced=await window.llanqueCloud.flush();showToast(synced?`Caja ${action} y sincronizada con Supabase.`:`Caja ${recordId} conservada localmente; Supabase no confirmó la sincronización. No repitas la operación.`,synced?3200:7500,synced?'':'warning');return synced}
function showCashDesk(){
 const active=cashSessions.find(session=>session.status==='ABIERTA')||null,mode=active?'close':'open',today=localDateValue();
 openModal('Apertura / Cierre de Caja',`<div class="cashdesk"><div class="cash-current ${active?'is-open':'is-closed'}">Caja actual: <strong>${active?'ABIERTA':'CERRADA'}</strong>${active?`<span>${escapeHtml(active.id)} · Abierta ${escapeHtml(active.openedAt||active.date)} · ${escapeHtml(active.user||'LLANQUE (DEMO)')}</span>`:''}</div><section class="cash-count-section"><div class="cash-section-heading"><h3>${mode==='open'?'Conteo para apertura':'Conteo para cierre'}</h3><span>${mode==='open'?'Ingresa la cantidad inicial por denominación.':'Cuenta el efectivo disponible al cerrar.'}</span></div>${cashCountsMarkup()}<div class="cash-grand-total"><strong>Total contado</strong><b id="cashGrandTotal">Bs. 0.00</b></div><div class="field cash-observations"><label for="cashObservations">Observaciones</label><textarea id="cashObservations" placeholder="Opcional"></textarea></div><p class="hint cash-disclaimer">Conteo de efectivo de esta demo. No se calcula contra ventas ni pagos del sistema.</p></section><section class="cash-history"><h3>Buscar flujos de Apertura / Cierre</h3><div class="cash-filter-grid"><div class="field"><label for="cashFilterStart">Fecha Inicio</label><input id="cashFilterStart" type="date"></div><div class="field"><label for="cashFilterEnd">Fecha Fin</label><input id="cashFilterEnd" type="date"></div><div class="field"><label for="cashFilterUser">Usuario</label><select id="cashFilterUser"><option value="all">Todos</option><option value="LLANQUE (DEMO)">LLANQUE (DEMO)</option></select></div><div class="field"><label for="cashFilterStatus">Estado</label><select id="cashFilterStatus"><option value="all">Todos</option><option>ABIERTA</option><option>CERRADA</option></select></div></div><div class="toolbar cash-filter-actions"><button class="btn btn-blue" id="cashSearch" type="button">Buscar</button><button class="btn btn-light" id="cashClear" type="button">Limpiar</button></div><div class="table-wrap cash-history-wrap"><table class="cash-history-table"><thead><tr><th>ID</th><th>Usuario</th><th>Fecha Apertura</th><th>Fecha Cierre</th><th class="num">Saldo Inicial</th><th class="num">Saldo Cierre</th><th>Estado</th><th>Acciones</th></tr></thead><tbody id="cashHistoryRows"></tbody></table></div><p class="hint" id="cashHistoryCount"></p></section><div class="dialog-actions cashdesk-footer"><button class="btn btn-light" id="cashDeskCancel" type="button">Cancelar</button><button class="btn ${mode==='open'?'btn-green':'btn-red'}" id="cashDeskSave" type="button">${mode==='open'?'⇧ Abrir Caja':'▣ Cerrar Caja'}</button></div></div>`);
 modal.classList.add('cashdesk-open');
 const counts=[...document.querySelectorAll('.cash-count')],grand=document.querySelector('#cashGrandTotal');
 const calculate=()=>{let total=0;counts.forEach(input=>{const qty=Math.max(0,Math.floor(Number(input.value)||0)),amount=Number(input.dataset.denomination),subtotal=qty*amount;total+=subtotal;input.closest('tr').querySelector('.cash-subtotal').textContent=cashMoney(subtotal)});grand.textContent=cashMoney(total);return total};counts.forEach(input=>input.addEventListener('input',calculate));
 const paintHistory=()=>{const from=document.querySelector('#cashFilterStart').value,to=document.querySelector('#cashFilterEnd').value,user=document.querySelector('#cashFilterUser').value,status=document.querySelector('#cashFilterStatus').value,rows=cashSessions.filter(session=>(!from||session.date>=from)&&(!to||session.date<=to)&&(user==='all'||session.user===user)&&(status==='all'||session.status===status)).slice().reverse();document.querySelector('#cashHistoryRows').innerHTML=rows.length?rows.map(session=>`<tr><td><strong>${escapeHtml(session.id)}</strong></td><td>${escapeHtml(session.user||'LLANQUE (DEMO)')}</td><td>${escapeHtml(session.openedAt||session.date)}</td><td>${escapeHtml(session.closedAt||'—')}</td><td class="num">${cashMoney(session.openingAmount)}</td><td class="num">${session.closingAmount==null?'—':cashMoney(session.closingAmount)}</td><td><span class="cash-status ${session.status==='ABIERTA'?'open':'closed'}">${escapeHtml(session.status)}</span></td><td>${session.status==='ABIERTA'?`<button class="mini-action" type="button" data-cash-close="${escapeHtml(session.id)}">Cerrar</button>`:`<button class="mini-action" type="button" data-cash-detail="${escapeHtml(session.id)}">Ver</button>`}</td></tr>`).join(''):'<tr><td colspan="8" class="empty">No hay aperturas o cierres para los filtros seleccionados.</td></tr>';document.querySelector('#cashHistoryCount').textContent=`${rows.length} registro${rows.length===1?'':'s'} de caja`;document.querySelectorAll('[data-cash-close]').forEach(button=>button.onclick=()=>showCashDesk());document.querySelectorAll('[data-cash-detail]').forEach(button=>button.onclick=()=>showCashSessionDetail(cashSessions.find(session=>session.id===button.dataset.cashDetail)))};
 document.querySelector('#cashSearch').onclick=paintHistory;document.querySelector('#cashClear').onclick=()=>{document.querySelector('#cashFilterStart').value='';document.querySelector('#cashFilterEnd').value='';document.querySelector('#cashFilterUser').value='all';document.querySelector('#cashFilterStatus').value='all';paintHistory()};document.querySelector('#cashDeskCancel').onclick=closeModal;
 document.querySelector('#cashDeskSave').onclick=async()=>{const countsData=Object.fromEntries(counts.map(input=>[input.dataset.denomination,Math.max(0,Math.floor(Number(input.value)||0))])),amount=calculate(),observation=document.querySelector('#cashObservations').value.trim(),now=new Date(),time=now.toLocaleString('es-BO');if(mode==='open'){if(cashSessions.some(session=>session.status==='ABIERTA')){showToast('Ya existe una caja abierta.');return}const record={id:'CJ-'+now.getTime().toString().slice(-8),date:today,openedAt:time,openedAtIso:now.toISOString(),user:'LLANQUE (DEMO)',status:'ABIERTA',openingCounts:countsData,openingAmount:amount,openingNotes:observation};cashSessions.push(record);closeModal();await syncCashSessions(record.id,'abierta')}else{const session=cashSessions.find(item=>item.id===active?.id&&item.status==='ABIERTA');if(!session){showToast('La caja ya está cerrada o no está disponible.');return}session.status='CERRADA';session.closedAt=time;session.closedAtIso=now.toISOString();session.closingCounts=countsData;session.closingAmount=amount;session.closingNotes=observation;closeModal();await syncCashSessions(session.id,'cerrada')}};
 paintHistory();calculate();
}
function showCashSessionDetail(session){if(!session)return;const renderCounts=counts=>cashDenominations.map(value=>`<tr><td>Bs. ${value.toFixed(value%1?1:0)}</td><td>${Number(counts?.[String(value)])||0}</td><td class="num">${cashMoney((Number(counts?.[String(value)])||0)*value)}</td></tr>`).join('');openModal(`Detalle de Caja · ${session.id}`,`<div class="cash-detail"><p><b>Estado:</b> ${escapeHtml(session.status)}<br><b>Usuario:</b> ${escapeHtml(session.user||'LLANQUE (DEMO)')}<br><b>Apertura:</b> ${escapeHtml(session.openedAt||session.date)}<br><b>Cierre:</b> ${escapeHtml(session.closedAt||'—')}</p><h3>Conteo inicial</h3><div class="table-wrap"><table class="cash-detail-table"><thead><tr><th>Denominación</th><th>Cantidad</th><th class="num">Subtotal</th></tr></thead><tbody>${renderCounts(session.openingCounts)}</tbody><tfoot><tr><th colspan="2">Total inicial</th><th class="num">${cashMoney(session.openingAmount)}</th></tr></tfoot></table></div>${session.closingCounts?`<h3>Conteo de cierre</h3><div class="table-wrap"><table class="cash-detail-table"><thead><tr><th>Denominación</th><th>Cantidad</th><th class="num">Subtotal</th></tr></thead><tbody>${renderCounts(session.closingCounts)}</tbody><tfoot><tr><th colspan="2">Total cierre</th><th class="num">${cashMoney(session.closingAmount)}</th></tr></tfoot></table></div>`:''}<p><b>Observaciones de apertura:</b> ${escapeHtml(session.openingNotes||'—')}<br><b>Observaciones de cierre:</b> ${escapeHtml(session.closingNotes||'—')}</p><div class="dialog-actions"><button class="btn btn-light" id="cashDetailClose">Cerrar</button></div></div>`);document.querySelector('#cashDetailClose').onclick=closeModal}




/* Servicios: registro, consulta, cierre y exportación guardados en la clave sincronizada. */
function readDemoServices(){try{const rows=JSON.parse(localStorage.getItem('llanque-demo-services')||'[]');return Array.isArray(rows)?rows:[]}catch{return []}}
async function writeDemoServices(rows,successMessage){try{localStorage.setItem('llanque-demo-services',JSON.stringify(rows))}catch(error){showToast('No se guardó el servicio: el almacenamiento está lleno.',6500,'warning');return false}if(!window.llanqueCloud?.flush){showToast(successMessage+' Quedó guardado localmente; no hay sesión de Supabase.',6500,'warning');return false}const synced=await window.llanqueCloud.flush();showToast(synced?successMessage+' Sincronizado con Supabase.':successMessage+' Guardado localmente, pero Supabase no confirmó la sincronización.',6500,synced?'':'warning');return synced}
function showServiceRegister(){
 const today=localDateValue();openModal('Registrar Servicio',`<div class="grid"><div class="field"><label for="serviceDate">Fecha *</label><input type="date" id="serviceDate" value="${today}"></div><div class="field"><label for="serviceClient">Cliente</label><input id="serviceClient" list="serviceClientOptions" placeholder="Nombre del cliente"><datalist id="serviceClientOptions">${clients.map(client=>`<option value="${escapeHtml(client.name)}"></option>`).join('')}</datalist></div><div class="field full"><label for="serviceDescription">Servicio realizado *</label><input id="serviceDescription" placeholder="Descripción del servicio"></div><div class="field"><label for="serviceAmount">Monto (Bs.) *</label><input id="serviceAmount" type="number" min="0" step="0.01" value="0"></div><div class="field"><label for="serviceStatus">Estado</label><select id="serviceStatus"><option>Pendiente</option><option>Completado</option></select></div><div class="field full"><label for="serviceNotes">Observaciones</label><textarea id="serviceNotes" placeholder="Detalle opcional"></textarea></div></div><p class="hint">El servicio se guarda en el estado compartido de LLANQUE.</p><div class="dialog-actions"><button class="btn btn-light" id="serviceCancel" type="button">Cancelar</button><button class="btn btn-green" id="serviceSave" type="button">Guardar servicio</button></div>`);
 document.querySelector('#serviceCancel').onclick=closeModal;document.querySelector('#serviceSave').onclick=async()=>{const date=document.querySelector('#serviceDate').value,client=document.querySelector('#serviceClient').value.trim(),description=document.querySelector('#serviceDescription').value.trim(),amount=Number(document.querySelector('#serviceAmount').value),status=document.querySelector('#serviceStatus').value,notes=document.querySelector('#serviceNotes').value.trim();if(!date||!description||!Number.isFinite(amount)||amount<0){showToast('Completa fecha, descripción y un monto válido.');return}const rows=readDemoServices(),record={id:'SR-'+Date.now().toString().slice(-8),date,client,description,amount,status,notes,user:'LLANQUE (DEMO)',created:new Date().toISOString()};rows.push(record);closeModal();await writeDemoServices(rows,`Servicio ${record.id} guardado.`)};
}
function showServiceHistory(){
 const draw=(query='')=>{const q=query.trim().toLocaleLowerCase('es'),rows=readDemoServices().slice().reverse().filter(record=>`${record.id} ${record.date} ${record.client} ${record.description} ${record.status}`.toLocaleLowerCase('es').includes(q));openModal('Historial de Servicios',`<div class="toolbar service-history-tools"><input id="serviceHistorySearch" type="search" placeholder="Buscar servicio, cliente o estado" value="${escapeHtml(query)}"><button class="btn btn-light" id="serviceExport" type="button">Descargar Excel</button><button class="btn btn-green" id="serviceNew" type="button">＋ Registrar servicio</button></div><div class="table-wrap"><table class="service-history-table"><thead><tr><th>Documento</th><th>Fecha</th><th>Cliente</th><th>Servicio</th><th>Estado</th><th class="num">Monto</th><th>Acciones</th></tr></thead><tbody>${rows.length?rows.map(record=>`<tr><td>${escapeHtml(record.id)}</td><td>${escapeHtml(record.date)}</td><td>${escapeHtml(record.client||'—')}</td><td>${escapeHtml(record.description)}</td><td>${escapeHtml(record.status)}</td><td class="num">${treasuryMoney(record.amount)}</td><td><button class="mini-action" data-service-view="${escapeHtml(record.id)}" type="button">Ver</button>${record.status!=='Completado'?`<button class="mini-action" data-service-complete="${escapeHtml(record.id)}" type="button">Completar</button>`:''}<button class="mini-action danger-action" data-service-delete="${escapeHtml(record.id)}" type="button">Borrar</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty">No hay servicios registrados con este filtro.</td></tr>'}</tbody></table></div><p class="hint">Servicios guardados en la instalación de LLANQUE.</p><div class="dialog-actions"><button class="btn btn-light" id="serviceHistoryClose" type="button">Cerrar</button></div>`);
  document.querySelector('#serviceHistoryClose').onclick=closeModal;document.querySelector('#serviceNew').onclick=showServiceRegister;document.querySelector('#serviceHistorySearch').oninput=event=>{const caret=event.target.selectionStart;draw(event.target.value);const next=document.querySelector('#serviceHistorySearch');next.focus();next.setSelectionRange(caret,caret)};
  document.querySelector('#serviceExport').onclick=()=>{const all=readDemoServices().filter(record=>`${record.id} ${record.date} ${record.client} ${record.description} ${record.status}`.toLocaleLowerCase('es').includes(q));if(!all.length){showToast('No hay servicios para descargar.');return}downloadCsv('LLANQUE_servicios.csv',['Documento','Fecha','Cliente','Servicio','Monto (Bs.)','Estado','Observaciones','Usuario'],all.map(record=>[record.id,record.date,record.client,record.description,record.amount,record.status,record.notes,record.user]));showToast('Historial de servicios descargado para Excel.')};
  document.querySelectorAll('[data-service-view]').forEach(button=>button.onclick=()=>showServiceDetail(readDemoServices().find(record=>record.id===button.dataset.serviceView),()=>draw(query)));
  document.querySelectorAll('[data-service-complete]').forEach(button=>button.onclick=async()=>{const all=readDemoServices(),record=all.find(item=>item.id===button.dataset.serviceComplete);if(!record)return;record.status='Completado';await writeDemoServices(all,`Servicio ${record.id} completado.`);draw(query)});
  document.querySelectorAll('[data-service-delete]').forEach(button=>button.onclick=async()=>{const all=readDemoServices(),record=all.find(item=>item.id===button.dataset.serviceDelete);if(!record||!confirm(`¿Borrar el servicio ${record.id}?`))return;const next=all.filter(item=>item.id!==record.id);await writeDemoServices(next,`Servicio ${record.id} borrado.`);draw(query)});
 };draw();
}
function showServiceDetail(record,onBack){if(!record)return;openModal(`Servicio ${record.id}`,`<div class="service-detail"><p><b>Fecha:</b> ${escapeHtml(record.date)}<br><b>Cliente:</b> ${escapeHtml(record.client||'—')}<br><b>Descripción:</b> ${escapeHtml(record.description)}<br><b>Monto:</b> ${treasuryMoney(record.amount)}<br><b>Estado:</b> ${escapeHtml(record.status)}<br><b>Observaciones:</b> ${escapeHtml(record.notes||'—')}<br><b>Usuario:</b> ${escapeHtml(record.user||'LLANQUE (DEMO)')}</p><div class="dialog-actions"><button class="btn btn-light" id="serviceDetailBack" type="button">Volver</button><button class="btn btn-blue" id="serviceDetailClose" type="button">Cerrar</button></div></div>`);document.querySelector('#serviceDetailBack').onclick=onBack;document.querySelector('#serviceDetailClose').onclick=closeModal}


// Enlace protegido a la administración de usuarios y contraseñas.
(()=>{const logout=document.querySelector('#logoutBtn');if(!logout||document.querySelector('#accountSettingsLink'))return;const link=document.createElement('a');link.id='accountSettingsLink';link.className='btn btn-light account-settings-link';link.href='https://supabase.com/dashboard/project/bwrdebzsceygaivtacen/auth/users';link.target='_blank';link.rel='noopener noreferrer';link.title='Administrar cuentas y contraseñas';link.setAttribute('aria-label','Configuración: administrar cuentas y contraseñas');link.innerHTML='<span aria-hidden="true">⚙</span><span>Accesos</span>';logout.before(link)})();
